package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"

	node "github.com/jepsen-io/maelstrom/demo/go"
)

// EchoRequest represents the input echo request
type EchoRequest struct {
	Type    string     `json:"type"`
	MessageID int      `json:"msg_id,omitempty"`
	Echo    json.RawMessage `json:"echo,omitempty"`
}

// EchoResponse represents the output echo_ok response
type EchoResponse struct {
	Type        string  `json:"type"`
	InReplyTo   int     `json:"in_reply_to,omitempty"`
	Echo        json.RawMessage `json:"echo,omitempty"`
}

func main() {
	n, ok := node.NewNode(os.Stdin, os.Stdout)
	if !ok {
		log.Fatal("Failed to create new Maelstrom node")
	}
	defer n.Run()

	for {
		msg, err := n.Handle()
		if err != nil {
			log.Printf("Error handling message: %v", err)
			continue
		}

		switch msg.Type {
		case "init":
			// Handle init message - node already gets its own ID and list of all nodes' IDs from NewNode
			log.Printf("Initialized. Node ID: %d", n.ID())
		case "echo":
			var req EchoRequest
			err := json.Unmarshal(msg.Body, &req)
			if err != nil {
				log.Printf("Error parsing echo request: %v", err)
				continue
			}

			var resp EchoResponse
			resp.Type = "echo_ok"
			resp.InReplyTo = req.MessageID
			resp.Echo = msg.Body // The same echo value as the request

			err = n.Reply(&resp, msg.ID)
			if err != nil {
				log.Printf("Error replying: %v", err)
			}
		default:
			log.Printf("Unhandled message type: %s", msg.Type)
		}
	}
}

